out = []
orig = {}
for e in data:
    line = e["line"]
    masked = e["masked"]
    orig[line] = masked
    if line in T:
        f, r = T[line]
        assert f in masked, ("MISS", line, f)
        translated = masked.replace(f, r, 1)
    else:
        translated = masked
    out.append({"line": line, "translated": translated})

json.dump(out, open(DST, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print("total", len(out), "changed", sum(1 for x in out if x["translated"] != orig[x["line"]]))